#include "calendar/google_api.hpp"
#include "calendar/time.hpp"
#include "project/process.hpp"
#include <nlohmann/json.hpp>
#include <iomanip>
#include <sstream>
#include <stdexcept>
#include <ctime>

using json=nlohmann::json;
namespace kepp::calendar {namespace {
std::string enc(const std::string&s){std::ostringstream o;o<<std::hex<<std::uppercase;for(unsigned char c:s)if(std::isalnum(c)||c=='-'||c=='_'||c=='.'||c=='~')o<<c;else o<<'%'<<std::setw(2)<<std::setfill('0')<<(int)c;return o.str();}
std::string to_seoul(const std::string&s){if(s.size()<19)return s;std::tm t{};int y,m,d,h,minute,sec;if(std::sscanf(s.c_str(),"%d-%d-%dT%d:%d:%d",&y,&m,&d,&h,&minute,&sec)!=6)return s;t.tm_year=y-1900;t.tm_mon=m-1;t.tm_mday=d;t.tm_hour=h;t.tm_min=minute;t.tm_sec=sec;int offset=0;if(s.back()!='Z'){auto pos=s.find_last_of("+-");if(pos!=std::string::npos&&pos>10){int oh=0,om=0;if(std::sscanf(s.c_str()+pos+1,"%d:%d",&oh,&om)==2)offset=(oh*60+om)*(s[pos]=='-'?-1:1);}}auto epoch=::timegm(&t)-offset*60+9*3600;auto out=*std::gmtime(&epoch);char b[26];std::strftime(b,sizeof b,"%Y-%m-%dT%H:%M:%S",&out);return std::string(b)+"+09:00";}
CalendarEvent parse_event(const json&j,const std::string&cid,bool writable){CalendarEvent e;e.id=j.value("id","");e.calendar_id=cid;e.title=j.value("summary","(untitled)");e.description=j.value("description","");e.etag=j.value("etag","");e.recurring=j.contains("recurringEventId");e.writable=writable&&!e.recurring;auto s=j.value("start",json::object()),n=j.value("end",json::object());e.all_day=s.contains("date");e.start=s.value(e.all_day?"date":"dateTime","");e.end=n.value(e.all_day?"date":"dateTime","");if(!e.all_day){e.start=to_seoul(e.start);e.end=to_seoul(e.end);}return e;}
std::string event_json(const EventInput&i){json j={{"summary",i.title},{"description",i.description}};if(i.all_day){j["start"]={{"date",i.start}};j["end"]={{"date",i.end}};}else{j["start"]={{"dateTime",i.start}};j["end"]={{"dateTime",i.end}};}return j.dump();}
}
GoogleApi::GoogleApi(AuthStore a,HttpRunner r):auth_(std::move(a)),runner_(std::move(r)){if(!runner_)runner_=[](const std::string&m,const std::string&u,const std::string&b,const std::vector<std::string>&h){std::vector<std::string>a={"curl","--silent","--show-error","-X",m,u,"-w","\n%{http_code}"};for(auto&x:h){a.push_back("-H");a.push_back(x);}if(!b.empty()){a.push_back("-H");a.push_back("Content-Type: application/json");a.push_back("--data");a.push_back(b);}auto r=project::run_captured(a,std::filesystem::current_path());if(r.exit_code)return HttpResponse{0,r.output};auto p=r.output.rfind('\n');if(p==std::string::npos)return HttpResponse{0,r.output};return HttpResponse{std::stoi(r.output.substr(p+1)),r.output.substr(0,p)};};}
HttpResponse GoogleApi::request(const std::string&m,const std::string&u,const std::string&b,std::vector<std::string>h){h.push_back("Authorization: Bearer "+auth_.access_token());auto r=runner_(m,u,b,h);if(r.status<200||r.status>=300){if(r.status==412)throw std::runtime_error("Calendar event changed on the server (412); refresh before editing");if(r.status==401)throw std::runtime_error("Google authorization expired (401)");if(r.status==403)throw std::runtime_error("Calendar permission or quota error (403)");if(r.status==429)throw std::runtime_error("Google Calendar rate limit reached (429)");throw std::runtime_error("Google Calendar request failed ("+std::to_string(r.status)+"): "+r.body);}return r;}
std::vector<CalendarInfo> GoogleApi::calendars(){std::vector<CalendarInfo>o;std::string page;do{auto u="https://www.googleapis.com/calendar/v3/users/me/calendarList"+(page.empty()?std::string{}:"?pageToken="+enc(page));auto j=json::parse(request("GET",u).body);for(auto&x:j.value("items",json::array()))o.push_back({x.value("id",""),x.value("summary",""),x.value("backgroundColor",""),x.value("selected",true),x.value("accessRole","")!="reader"&&x.value("accessRole","")!="freeBusyReader"});page=j.value("nextPageToken","");}while(!page.empty());return o;}
std::vector<CalendarEvent> GoogleApi::events(const std::string&cid,const WeekRange&w){std::vector<CalendarEvent>o;std::string page;do{auto u="https://www.googleapis.com/calendar/v3/calendars/"+enc(cid)+"/events?singleEvents=true&timeMin="+enc(w.monday+"T00:00:00+09:00")+"&timeMax="+enc(w.next_monday+"T00:00:00+09:00")+"&maxResults=2500"+(page.empty()?"":"&pageToken="+enc(page));auto j=json::parse(request("GET",u).body);for(auto&x:j.value("items",json::array()))o.push_back(parse_event(x,cid,true));page=j.value("nextPageToken","");}while(!page.empty());return o;}
CalendarEvent GoogleApi::create(const EventInput&i){std::string e; if(!valid_event(i,e))throw std::runtime_error(e);auto u="https://www.googleapis.com/calendar/v3/calendars/"+enc(i.calendar_id)+"/events";return parse_event(json::parse(request("POST",u,event_json(i)).body),i.calendar_id,true);}
CalendarEvent GoogleApi::update(const CalendarEvent&e,const EventInput&i){if(!e.writable||e.recurring)throw std::runtime_error("This event is read-only");std::string x;if(!valid_event(i,x))throw std::runtime_error(x);auto u="https://www.googleapis.com/calendar/v3/calendars/"+enc(e.calendar_id)+"/events/"+enc(e.id);return parse_event(json::parse(request("PATCH",u,event_json(i),{"If-Match: "+e.etag}).body),e.calendar_id,true);}
void GoogleApi::remove(const CalendarEvent&e){if(!e.writable||e.recurring)throw std::runtime_error("This event is read-only");auto u="https://www.googleapis.com/calendar/v3/calendars/"+enc(e.calendar_id)+"/events/"+enc(e.id);request("DELETE",u,"",{"If-Match: "+e.etag});}
} // namespace kepp::calendar
